import numpy as np
from scipy.optimize import minimize

def objective(x):
    p, q, r, s = x
    return p/q + r/p + s/r + q/s

def constraint(x):
    p, q, r, s = x
    return (p + s) * (r + q) - (p * s + q * r)

def solve():
    best_f = float('inf')
    for i in range(200):
        x0 = np.random.rand(4) * 10 + 0.1
        res = minimize(objective, x0, method='SLSQP', 
                        bounds=((1e-6, None), (1e-6, None), (1e-6, None), (1e-6, None)),
                        constraints={'type': 'eq', 'fun': constraint})
        if res.success and res.fun < best_f:
            best_f = res.fun
    return best_f

print(solve())

def solve_for_rs(r, s):
    # x = (qr - sr - sq) / (qr + q^2 - sq)
    # f(q) = x + r/(xq) + s/r + q/s
    # We need q > sr/(r-s) if r > s
    # or q < s-r if s > r

    def f(q):
        num = q*r - s*r - s*q
        den = q*r + q**2 - s*q
        x = num / den
        if x <= 0: return float('inf')
        return x + r/(x*q) + s/r + q/s

    best_f = float('inf')
    # Search for q
    if r > s:
        q_min = s*r / (r-s)
        for q in np.linspace(q_min + 0.1, q_min + 20, 1000):
            best_f = min(best_f, f(q))
    else:
        q_max = s - r
        for q in np.linspace(0.1, q_max - 0.1, 1000):
            best_f = min(best_f, f(q))
    return best_f

results = []
for r in range(1, 20):
    for s in range(1, 20):
        if r != s:
            results.append(solve_for_rs(r, s))

print(min(results))

